130	    /**
131	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
132	     * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first
133	     * three letters of the last name and NNNN a per-city 4-digit zero-padded sequence equal to one
134	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
135	     *
136	     * @param city the owner's city
137	     * @param lastName the owner's last name
138	     * @return the assigned customer code
139	     */
140	    private String assignCustomerCode(String city, String lastName) {
141	        String city3 = prefix3(city);
142	        String last3 = prefix3(lastName);
143	        String cityValue = city == null ? "" : city;
144	        int sequence = (int) this.clinicService.findAllOwners().stream()
145	            .filter(existing -> cityValue.equalsIgnoreCase(
146	                existing.getCity() == null ? "" : existing.getCity()))
147	            .count() + 1;
148	        return String.format("%s-%s-%04d", city3, last3, sequence);
149	    }
150	
151	    /**
152	     * Returns the upper-cased first three letters of the given value, or fewer if the value is
153	     * shorter, treating {@code null} as empty.
154	     */
155	    private String prefix3(String value) {
156	        String name = value == null ? "" : value;
157	        return name.substring(0, Math.min(3, name.length()))
158	            .toUpperCase(java.util.Locale.ROOT);
159	    }
160	
161	    /**
162	     * Counts how many existing owners share the given first and last name, compared
163	     * case-insensitively, at the time this owner is created. The value excludes the owner
164	     * being created (which has not yet been saved) and is stored on the new owner and returned
165	     * as its {@code namesakeCount}.
166	     *
167	     * @param firstName the first name of the owner being created
168	     * @param lastName the last name of the owner being created
169	     * @return the number of existing owners with the same first and last name
170	     */
171	    private int countNamesakes(String firstName, String lastName) {
172	        String first = firstName == null ? "" : firstName;
173	        String last = lastName == null ? "" : lastName;
174	        return (int) this.clinicService.findAllOwners().stream()
175	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
176	                && last.equalsIgnoreCase(existing.getLastName()))
177	            .count();
178	    }
179	
180	    /**
181	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
182	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
183	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
184	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
185	     * {@code "+61412345678"}. The E.164 value is stored and returned.
186	     *
187	     * @param telephone the raw telephone as submitted
188	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
189	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
190	     */
191	    private String normalizeTelephone(String telephone) {
192	        String raw = telephone == null ? "" : telephone.trim();
193	        boolean hasCountryCode = raw.startsWith("+");
194	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
195	        if (hasCountryCode) {
196	            cleaned = cleaned.substring(1);
197	        }
198	        String digits;
199	        if (hasCountryCode) {
200	            digits = cleaned;
201	        } else {
202	            if (cleaned.startsWith("0")) {
203	                cleaned = cleaned.substring(1);
204	            }
205	            digits = "61" + cleaned;
206	        }
207	        if (!digits.matches("[0-9]{8,15}")) {
208	            throw new InvalidTelephoneException(telephone);
209	        }
210	        return "+" + digits;
211	    }
212	
213	    /**
214	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
215	     * multi-character top-level label. Deliberately lenient about the exact character set while still
216	     * rejecting values that are clearly not addresses (e.g. missing '@').
217	     */
218	    private static final java.util.regex.Pattern EMAIL_PATTERN =
219	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
220	
221	    /**
222	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
223	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
224	     * lower-cased before being stored and returned.
225	     *
226	     * @param email the raw email as submitted, may be {@code null}
227	     * @return the lower-cased email, or {@code null} when none was supplied
228	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
229	     */
230	    private String normalizeEmail(String email) {
231	        if (email == null || email.isBlank()) {
232	            return null;
233	        }
234	        String trimmed = email.trim();
235	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
236	            throw new InvalidEmailException(email);
237	        }
238	        return trimmed.toLowerCase(java.util.Locale.ROOT);
239	    }
240	
241	    /**
242	     * Common street-type abbreviations expanded to their full word during address normalization.
243	     */
244	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
245	        "ST", "STREET",
246	        "RD", "ROAD",
247	        "AVE", "AVENUE");
248	
249	    /**
250	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
251	     * whitespace collapse to a single space, the value is upper-cased and common street-type
252	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
253	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
254	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
255	     * for every address comparison (household duplicate detection and the shared household id).
256	     *
257	     * @param address the raw address as submitted
258	     * @return the normalized address
259	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
260	     */
261	    private String normalizeAddress(String address) {
262	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
263	        if (collapsed.isEmpty()) {
264	            throw new InvalidAddressException(address);
265	        }
266	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
267	        StringBuilder normalized = new StringBuilder(collapsed.length());
268	        for (int i = 0; i < tokens.length; i++) {
269	            if (i > 0) {
270	                normalized.append(' ');
271	            }
272	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
273	        }
274	        return normalized.toString();
275	    }
276	
277	    /**
278	     * Rejects creating an owner whose E.164 telephone is already used by another owner. Telephones of
279	     * existing owners are normalized to E.164 the same way before comparison, so equivalent numbers
280	     * submitted in different formats (e.g. national {@code "0412 345 678"} and international
281	     * {@code "+61 412 345 678"}) are still treated as duplicates.
282	     *
283	     * @param telephone the E.164 telephone of the owner being created
284	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
285	     */
286	    private void rejectDuplicateTelephone(String telephone) {
287	        boolean duplicate = this.clinicService.findAllOwners().stream()
288	            .map(Owner::getTelephone)
289	            .filter(existing -> existing != null)
290	            .map(this::toE164OrNull)
291	            .filter(existing -> existing != null)
292	            .anyMatch(telephone::equals);
293	        if (duplicate) {
294	            throw new DuplicateTelephoneException(telephone);
295	        }
296	    }
297	
298	    /**
299	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
300	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number.
301	     */
302	    private String toE164OrNull(String telephone) {
303	        try {
304	            return normalizeTelephone(telephone);
305	        } catch (InvalidTelephoneException e) {
306	            return null;
307	        }
308	    }
309	
310	    /**
311	     * Rejects creating an owner who shares a household with an existing owner, i.e. another owner
312	     * already has the same last name and the same address. Last names are compared case-insensitively
313	     * with whitespace collapsed; addresses are compared in their normalized form (see
314	     * {@link #normalizeAddress}, which every owner's stored address already uses), so values that
315	     * differ only in letter case, spacing or a common street-type abbreviation still count as a match.
316	     * This check is skipped when the request sets {@code sharesHousehold} to {@code true}.
317	     *
318	     * @param lastName the last name of the owner being created
319	     * @param address the normalized address of the owner being created
320	     * @throws DuplicateHouseholdException (409 Conflict) if another owner shares this household
321	     */
322	    private void rejectDuplicateHousehold(String lastName, String address) {
323	        String normalizedLastName = Households.normalize(lastName);
324	        String normalizedAddress = Households.normalize(address);
325	        boolean duplicate = this.clinicService.findAllOwners().stream()
326	            .anyMatch(existing ->
327	                Households.normalize(existing.getLastName()).equals(normalizedLastName)
328	                    && Households.normalize(existing.getAddress()).equals(normalizedAddress));
329	        if (duplicate) {
330	            throw new DuplicateHouseholdException(lastName, address);
331	        }
332	    }
